"""Generate core/services/analytics_schema.gd from docs/spec/05_EXECUTION/ANALYTICS_EVENTS.csv.
Run: python tools/gen_analytics_schema.py [--check]
--check exits 1 if the generated file is out of date (use before commits/CI).
"""
from pathlib import Path
import argparse, csv, sys

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'docs/spec/05_EXECUTION/ANALYTICS_EVENTS.csv'
TARGET = ROOT / 'core/services/analytics_schema.gd'

def render():
    rows = list(csv.DictReader(SOURCE.open(encoding='utf-8-sig', newline='')))
    lines = [
        'class_name AnalyticsSchema',
        'extends RefCounted',
        '## GENERATED by tools/gen_analytics_schema.py from docs/spec/05_EXECUTION/ANALYTICS_EVENTS.csv.',
        '## Do not edit by hand; edit the CSV and regenerate.',
        '',
        '## event name (StringName) -> allowed property names (Array of String)',
        'const EVENTS: Dictionary = {',
    ]
    for row in rows:
        props = [p.strip() for p in row['properties_allowlist'].split(',') if p.strip()]
        quoted = ', '.join(f'"{p}"' for p in props)
        lines.append(f'\t&"{row["event_name"].strip()}": [{quoted}],')
    lines.append('}')
    return '\n'.join(lines) + '\n'

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    text = render()
    if args.check:
        current = TARGET.read_text(encoding='utf-8') if TARGET.exists() else ''
        if current != text:
            print(f'{TARGET.relative_to(ROOT)} is out of date; run python tools/gen_analytics_schema.py')
            return 1
        print('analytics schema up to date')
        return 0
    TARGET.write_text(text, encoding='utf-8', newline='\n')
    print(f'wrote {TARGET.relative_to(ROOT)} ({text.count(chr(10)) - 8} events)')
    return 0

if __name__ == '__main__':
    sys.exit(main())
